import collections,datetime,hashlib,json,math,shutil
from pathlib import Path
R=Path(__file__).resolve().parent;H=R.parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def write(n,d):(R/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
rows=[json.loads(x) for x in (H/'native_unit_admission_v1/ROW_ADMISSION.jsonl').read_text().splitlines()]
selected=[r for r in rows if r['plain_Witten_primary_point_eligible']]
assert len(selected)==85
manifest={'units':{},'source_sha256':sha(H/'native_unit_admission_v1/ROW_ADMISSION.jsonl'),'selection':'Exactly plain_Witten_primary_point_eligible; preserve original row metadata; no new exclusions'}
for unit in ['ug_ml_native','uM_native']:
 rs=[r for r in selected if r['native_unit_group']==unit];groups=sorted({r['source_family_group'] for r in rs});folds=[]
 for g in groups:
  train=[r for r in rs if r['source_family_group']!=g];val=[r for r in rs if r['source_family_group']==g]
  for key in ['peptide_id','sequence','annotation_fingerprint','sequence_family','source_family_group']:
   assert not ({r[key] for r in train}&{r[key] for r in val}),(unit,g,key)
  assert not (set(x for r in train for x in r['source_keys'])&set(x for r in val for x in r['source_keys'])),(unit,g,'source_keys')
  assert len({r['source_family_group'] for r in train})>=2
  folds.append({'fold_id':g,'train_activity_ids':[r['activity_id'] for r in train],'validation_activity_ids':[r['activity_id'] for r in val],'train_rows':len(train),'validation_rows':len(val),'train_peptides':len({r['peptide_id'] for r in train}),'validation_peptides':len({r['peptide_id'] for r in val}),'train_families':len({r['sequence_family'] for r in train}),'validation_families':len({r['sequence_family'] for r in val}),'train_groups':len(groups)-1,'validation_groups':1})
 manifest['units'][unit]={'rows':len(rs),'peptide_IDs':len({r['peptide_id'] for r in rs}),'families':len({r['sequence_family'] for r in rs}),'groups':len(groups),'folds':folds}
write('FOLDS.json',manifest)
(R/'DATA.jsonl').write_text(''.join(json.dumps(r,ensure_ascii=False,sort_keys=True)+'\n' for r in selected))
shutil.copyfile(H/'witten_cpu_v1/model.py',R/'model.py')
write('PROTOCOL.json',{'schema':'AMP_H5_NATIVE_BASELINE_PROTOCOL_V1','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'One finite native-unit exploratory development run; cache labels already exposed; no untouched confirmation, no protected H5/test37 participation or transfer of these checkpoints into original H5 evaluation','authorization':'Current delegated user explicitly authorizes bounded development baseline after scientific reassessment; previous no-training-turn flags remain historical, not overwritten','units_separate':['ug_ml_native','uM_native'],'target':'log10 of cached native positive point MIC lower_raw_unit; never interpret censors/ranges/plusminus as exact or convert unit','data':'Exactly85 flagged point rows,46 mass and39 molar. Unknown covariates and all original metadata retained; no complete-case deletion','split':'Leave one existing source-family union component out;10 mass folds and7 molar folds. Assert zero overlap of peptide ID/exact sequence/chemical fingerprint/family/source-group/known paper source keys. No row shuffling across folds; actual sizes recorded, refuse insufficient train groups','seed':1729,'models':['training_weighted_mean','composition_ridge','witten_CNN'],'train_weights':'Each training source-family group equal, each peptide within group equal, each observation within peptide equal:1/(G*P_g*n_i), sum1. All methods same train rows and weights','constant':'Training-weighted mean log10 label','ridge':{'features':'20AA exact-sequence fractions in fixed alphabet order plus log(length); no imputed chemistry or potency features','standardization':'Training-weighted mean/std only; zero std replaced1','alpha':1.0,'objective':'sum_i w_i(y_i-intercept-z_i beta)^2 + alpha*sum_j beta_j^2; intercept unpenalized','solver':'numpy.linalg.solve;21features fixed; no tuning'},'cnn':{'model_source_sha256':sha(H/'witten_cpu_v1/model.py'),'parameters':183069,'epochs':100,'updates_per_epoch':1,'batch':'All training rows, at most45 rows; full-batch repeated-observation weights exact','loss':'weighted squared error on native log10 target, weights sum1','optimizer':'KerasStyleAdam lr.001 betas.9/.999 epsilon_hat1e-7','initialization':'reset same seed1729 independently everyfold/unit; Glorot; dropout.5 as audited model','endpoint':'Exactly100updates, no validation loss used during fit, no early stopping, no schedules, no hyperparameter/seed search','adaptation':'Architecture-equivalent PyTorch, not author training-protocol or performance reproduction. Full batch weighted objective and100epochs are explicit development adaptations'},'evaluation':{'primary':'macro-group MAE = average over heldout source groups of average over peptides of average over records absolute log10 error','secondary':'sqrt(macro-group MSE), with same nested weights; not average of fold RMSE','sensitivities':['ordinary row-weighted MAE/RMSE','peptide-macro MAE/RMSE'],'metrics_scope':'Eachunit independently; no pooling numerical units, no confidence/significance or independent-generalization claims','predictions':'Write all OOF prediction rows once after each heldout fold, before aggregate scoring; retain raw unit/value/operator, peptide/family/group/source and missingness'},'limits':{'cpu_threads':1,'interop_threads':1,'blas_threads':1,'wall_seconds':600,'maximum_CNN_updates':1700,'peak_rss_bytes':1500000000,'process_nice_increment':10,'model_execution':'serial CPU only; no MPS/GPU; check active jobs before launch'},'failure_rules':['Any source/code/config/hash or fold-overlap mismatch aborts before model fit','Any nonfinite loss/gradient/prediction or absent model parameter gradient aborts entire run','Any resource limit stop preserves failure and completed folds; no retry or reseeding','Incomplete OOF rows produce only partial status, never aggregate success','No failure-dependent replacement data/fold/epoch choice'],'simple_signal_rule':'Describe point estimates versus constant only; no minimum advantage or statistically significant claim, report allmodel outcomes including negatives','prohibited':['new acquisition','new dependencies/weights','test37 or original train/dev file access','Caliber project access','source H0-H4/manuscript edits','new censored model','new scientific intervention','uploads/credentials'],'backup':'BACKUP_BLOCKED'})
write('PREFLIGHT.json',{'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'process_check':'Read-only ps under authorized escalation; no active AMP H5/Witten or Caliber solver seen among matching commands. Unrelated session_watcher ~94.7% one-core CPU; left untouched','model_slot':'ROOT_NATIVE_BASELINE_RESERVED_SERIAL','source_scope':'existing cached points only','CPU_budget':'1 thread nice+10 within user authorized600s; not inspecting/changing other projects'})
